      'LC_992':  { leetcode: 992,  title: 'Subarrays with K Different Integers',                   difficulty: 'Hard', freq: 'High',   status: 'Pending', templateRefs: ['T5'], tags: ['sliding-window','variable-window','counting','exactly-k','hash-map'], keyInsight: 'Direct exactly-K-distinct window is not monotonically valid. atMostK(k) - atMostK(k-1) is the only O(n) solution.', shrinkTrigger: 'freq.size > k (inside atMostK)', timeComplexity: 'O(n)', spaceComplexity: 'O(k)', gotcha: 'Same k < 0 guard as LC_930 — not optional.', faangNote: 'Google and Meta favourite. Tests whether you independently recognise that exactly-K is not directly solvable.', alternateApproaches: [], link: 'https://leetcode.com/problems/subarrays-with-k-different-integers/' },
