      'LC_1448': { leetcode: 1448, title: 'Count Good Nodes in Binary Tree', difficulty: 'Medium', freq: 'Medium', status: 'Pending', templateRefs: ['P1'], tags: ['tree','binary-tree','dfs','recursion'], keyInsight: 'Pass the max-so-far down the path; a node is good if its value is >= that max.', shrinkTrigger: 'dfs(node, maxSoFar = max(maxSoFar, node.val))', timeComplexity: 'O(n)', spaceComplexity: 'O(h)', gotcha: 'This is top-down accumulation (pass state down), the complement of bottom-up aggregation.', faangNote: null, alternateApproaches: [], link: 'https://leetcode.com/problems/count-good-nodes-in-binary-tree/' },
