      'LC_199':  { leetcode: 199,  title: 'Binary Tree Right Side View', difficulty: 'Medium', freq: 'Medium', status: 'Pending', templateRefs: ['P2'], tags: ['tree','binary-tree','bfs','level-order','dfs'], keyInsight: 'BFS: take the last node of each level. Or DFS visiting right-first and recording the first node seen per depth.', shrinkTrigger: 'on each level, push the node at index sz-1', timeComplexity: 'O(n)', spaceComplexity: 'O(n)', gotcha: 'DFS right-first with a depth==result.length check is an elegant alternative interviewers like.', faangNote: 'Very common at Meta/Amazon. Be able to give both the BFS and DFS solutions.', alternateApproaches: [{ technique: 'dfs', tradeoff: 'DFS right-first records first node per depth; O(h) space instead of O(n).', complexity: 'O(n) time, O(h) space' }], link: 'https://leetcode.com/problems/binary-tree-right-side-view/' },
      'LC_116':  { leetcode: 116,  title: 'Populating Next Right Pointers in Each Node', difficulty: 'Medium', freq: 'Medium', status: 'Pending', templateRefs: ['P2'], tags: ['tree','binary-tree','bfs','level-order'], keyInsight: 'Perfect tree: use the established next pointers of the current level to wire the level below in O(1) space.', shrinkTrigger: 'node.left.next = node.right; node.right.next = node.next?.left', timeComplexity: 'O(n)', spaceComplexity: 'O(1)', gotcha: 'The O(1)-space follow-up is the point. BFS with a queue is O(n) space and is the easy version.', faangNote: 'The constant-space level linking is the differentiator; lead with it.', alternateApproaches: [{ technique: 'level-order-bfs', tradeoff: 'Queue-based is simpler but O(n) space.', complexity: 'O(n) time, O(n) space' }], link: 'https://leetcode.com/problems/populating-next-right-pointers-in-each-node/' },
