      'LC_987':  { leetcode: 987,  title: 'Vertical Order Traversal of a Binary Tree', difficulty: 'Hard', freq: 'High', status: 'Pending', templateRefs: ['P2'], tags: ['tree','binary-tree','bfs','dfs','sorting'], keyInsight: 'Assign each node a (col, row) coordinate; group by column, then sort within a column by row, then by value.', shrinkTrigger: 'sort key = (col, row, val)', timeComplexity: 'O(n log n)', spaceComplexity: 'O(n)', gotcha: 'The tie-break rule — same position sorts by VALUE — is what makes this Hard, not the traversal.', faangNote: 'Amazon favorite. The whole difficulty is the precise ordering; state the (col,row,val) sort up front.', alternateApproaches: [], link: 'https://leetcode.com/problems/vertical-order-traversal-of-a-binary-tree/' },
