      'LC_449':  { leetcode: 449,  title: 'Serialize and Deserialize BST', difficulty: 'Medium', freq: 'Low', status: 'Pending', templateRefs: ['P4'], tags: ['tree','bst','serialize','dfs'], keyInsight: 'Because it is a BST, preorder alone (no null markers) suffices — reconstruct using a (low, high) bound while consuming.', shrinkTrigger: 'rebuild with valid range to know where each value belongs', timeComplexity: 'O(n)', spaceComplexity: 'O(n)', gotcha: 'The BST property lets you skip null markers, making the encoding more compact than LC_297.', faangNote: null, alternateApproaches: [], link: 'https://leetcode.com/problems/serialize-and-deserialize-bst/' },
