      'LC_437':  { leetcode: 437,  title: 'Path Sum III', difficulty: 'Medium', freq: 'Medium', status: 'Pending', templateRefs: ['P5'], tags: ['tree','binary-tree','path-sum','dfs','prefix-sum','hash-map'], keyInsight: 'Prefix-sum on the root-to-node path: count earlier prefixes equal to currentSum - target using a hashmap (like subarray-sum-equals-k on a path).', shrinkTrigger: 'count += seen.get(curSum - target); seen[curSum]++ ; backtrack seen[curSum]--', timeComplexity: 'O(n)', spaceComplexity: 'O(h)', gotcha: 'Decrement the prefix-count on backtrack, or counts leak across sibling branches. Paths need not start at root.', faangNote: 'The tree analogue of LC_560. Recognizing the prefix-sum reduction is the SDE3 signal.', alternateApproaches: [], link: 'https://leetcode.com/problems/path-sum-iii/' },
