      'LC_232':  { leetcode: 232,  title: 'Implement Queue using Stacks', difficulty: 'Easy', freq: 'Low', status: 'Pending', templateRefs: ['P1'], tags: ['stack','queue','design'], keyInsight: 'Two stacks: push onto in-stack; for pop/peek, if out-stack empty, drain in-stack into it. Amortized O(1).', shrinkTrigger: 'if out empty, move all in -> out, then pop out', timeComplexity: 'O(1) amortized', spaceComplexity: 'O(n)', gotcha: 'Only transfer when the out-stack is empty; transferring every time breaks the amortized bound.', faangNote: null, alternateApproaches: [], link: 'https://leetcode.com/problems/implement-queue-using-stacks/' },
