      'LC_1047': { leetcode: 1047, title: 'Remove All Adjacent Duplicates In String', difficulty: 'Easy', freq: 'Low', status: 'Pending', templateRefs: ['P1'], tags: ['stack','string','simulation'], keyInsight: 'Push chars; if the incoming char equals the stack top, pop instead of pushing.', shrinkTrigger: 'top == c ? pop : push(c)', timeComplexity: 'O(n)', spaceComplexity: 'O(n)', gotcha: 'The stack itself, joined, is the answer — no extra pass needed.', faangNote: null, alternateApproaches: [], link: 'https://leetcode.com/problems/remove-all-adjacent-duplicates-in-string/' },
      'LC_496':  { leetcode: 496,  title: 'Next Greater Element I', difficulty: 'Easy', freq: 'Medium', status: 'Pending', templateRefs: ['P2'], tags: ['stack','monotonic-stack','next-greater','hash-map'], keyInsight: 'Build a value->nextGreater map by sweeping nums2 with a decreasing monotonic stack; then look up nums1.', shrinkTrigger: 'while stack top < cur: map[pop] = cur', timeComplexity: 'O(n)', spaceComplexity: 'O(n)', gotcha: 'The monotonic stack is built on nums2; nums1 is just a lookup. This is the gentlest intro to the pattern.', faangNote: 'Use this to teach yourself the next-greater template before LC_739.', alternateApproaches: [], link: 'https://leetcode.com/problems/next-greater-element-i/' },
      'LC_503':  { leetcode: 503,  title: 'Next Greater Element II', difficulty: 'Medium', freq: 'Low', status: 'Pending', templateRefs: ['P2'], tags: ['stack','monotonic-stack','next-greater','circular'], keyInsight: 'Circular array: iterate 2n times using index % n so wrap-around next-greater is found.', shrinkTrigger: 'for i in 0..2n-1: use nums[i % n]', timeComplexity: 'O(n)', spaceComplexity: 'O(n)', gotcha: 'Only push real indices during the second pass; do not double-record answers.', faangNote: null, alternateApproaches: [], link: 'https://leetcode.com/problems/next-greater-element-ii/' },
      'LC_739':  { leetcode: 739,  title: 'Daily Temperatures', difficulty: 'Medium', freq: 'Medium', status: 'Pending', templateRefs: ['P2'], tags: ['stack','monotonic-stack','next-greater'], keyInsight: 'Decreasing stack of indices; when a warmer day arrives, pop and record the day gap for each popped index.', shrinkTrigger: 'while temps[stack.top] < cur: res[idx] = i - idx', timeComplexity: 'O(n)', spaceComplexity: 'O(n)', gotcha: 'Store INDICES (not temperatures) so you can compute the day distance.', faangNote: 'The archetypal monotonic-stack interview problem. If you know one, know this.', alternateApproaches: [], link: 'https://leetcode.com/problems/daily-temperatures/' },
      'LC_901':  { leetcode: 901,  title: 'Online Stock Span', difficulty: 'Medium', freq: 'Medium', status: 'Pending', templateRefs: ['P2'], tags: ['stack','monotonic-stack','design'], keyInsight: 'Stack of (price, span); on a new price, pop all spans of smaller-or-equal prices and accumulate their spans into the current one.', shrinkTrigger: 'while top.price <= price: span += pop.span', timeComplexity: 'O(1) amortized', spaceComplexity: 'O(n)', gotcha: 'Accumulate the popped spans rather than counting one-by-one; that is what keeps it amortized O(1).', faangNote: 'A streaming/design twist on previous-greater; common at Amazon.', alternateApproaches: [], link: 'https://leetcode.com/problems/online-stock-span/' },
      'LC_456':  { leetcode: 456,  title: '132 Pattern', difficulty: 'Medium', freq: 'High', status: 'Pending', templateRefs: ['P2'], tags: ['stack','monotonic-stack'], keyInsight: 'Scan right-to-left keeping a decreasing stack; track the largest popped value as a candidate "2". If any element < that candidate, a 132 pattern exists.', shrinkTrigger: 'if nums[i] < third: return true; while top < nums[i]: third = pop', timeComplexity: 'O(n)', spaceComplexity: 'O(n)', gotcha: 'The subtle part is that the popped value (the "2") is guaranteed to have a larger element ("3") to its right.', faangNote: 'A favorite trick question; the right-to-left + popped-max insight is non-obvious.', alternateApproaches: [], link: 'https://leetcode.com/problems/132-pattern/' },
      'LC_84':   { leetcode: 84,   title: 'Largest Rectangle in Histogram', difficulty: 'Hard', freq: 'Medium', status: 'Pending', templateRefs: ['P3'], tags: ['stack','monotonic-stack','histogram','area'], keyInsight: 'Increasing stack of indices; when a shorter bar appears, pop and compute area = poppedHeight * width, where width spans to the new bar and the new stack top.', shrinkTrigger: 'while h[stack.top] > h[i]: area = h[pop]*(i - newTop - 1)', timeComplexity: 'O(n)', spaceComplexity: 'O(n)', gotcha: 'Use a sentinel 0-height bar at the end to flush the stack; width calc with the index BELOW the popped one is the classic bug.', faangNote: 'The foundational area problem; LC_85 and many others reduce to it. Know the width formula cold.', alternateApproaches: [], link: 'https://leetcode.com/problems/largest-rectangle-in-histogram/' },
      'LC_85':   { leetcode: 85,   title: 'Maximal Rectangle', difficulty: 'Hard', freq: 'Medium', status: 'Pending', templateRefs: ['P3'], tags: ['stack','monotonic-stack','histogram','matrix','dp'], keyInsight: 'Build a histogram of consecutive 1s height for each row, then apply LC_84 to every row.', shrinkTrigger: 'heights[c] = matrix[r][c]==1 ? heights[c]+1 : 0; then largestRectangle(heights)', timeComplexity: 'O(rows*cols)', spaceComplexity: 'O(cols)', gotcha: 'Reset a column height to 0 on a 0 cell. The whole problem is "LC_84 per row".', faangNote: 'Recognizing the reduction to LC_84 is the entire interview signal.', alternateApproaches: [], link: 'https://leetcode.com/problems/maximal-rectangle/' },
      'LC_42':   { leetcode: 42,   title: 'Trapping Rain Water', difficulty: 'Hard', freq: 'Medium', status: 'Pending', templateRefs: ['P3'], tags: ['stack','monotonic-stack','two-pointers','array'], keyInsight: 'Water above a bar = min(maxLeft, maxRight) - height. Two-pointer with running maxes is the cleanest O(1)-space solution; a decreasing stack also works.', shrinkTrigger: 'move the smaller side inward, adding (maxSide - height)', timeComplexity: 'O(n)', spaceComplexity: 'O(1)', gotcha: 'Two pointers beats the stack and DP-arrays approaches on space; lead with it but know all three.', faangNote: 'Asked everywhere. Present two-pointer O(1) space as the optimal; mention stack/DP as alternates.', alternateApproaches: [{ technique: 'monotonic-stack', tradeoff: 'Stack accumulates trapped water layer by layer; O(n) space.', complexity: 'O(n) time, O(n) space' }, { technique: 'prefix max arrays', tradeoff: 'Precompute maxLeft/maxRight arrays; simplest to reason about.', complexity: 'O(n) time, O(n) space' }], link: 'https://leetcode.com/problems/trapping-rain-water/' },
      'LC_907':  { leetcode: 907,  title: 'Sum of Subarray Minimums', difficulty: 'Medium', freq: 'Medium', status: 'Pending', templateRefs: ['P3'], tags: ['stack','monotonic-stack','contribution','array'], keyInsight: 'Contribution counting: each element is the min of (distance to previous-smaller) * (distance to next-smaller) subarrays; sum value * that count.', shrinkTrigger: 'count = left * right where left/right are nearest-smaller spans', timeComplexity: 'O(n)', spaceComplexity: 'O(n)', gotcha: 'Use strict on one side and non-strict on the other to avoid double-counting equal elements.', faangNote: 'The contribution technique generalizes to subarray ranges/maxes; a strong SDE3 pattern.', alternateApproaches: [], link: 'https://leetcode.com/problems/sum-of-subarray-minimums/' },
