      'LC_224':  { leetcode: 224,  title: 'Basic Calculator', difficulty: 'Hard', freq: 'Medium', status: 'Pending', templateRefs: ['P4'], tags: ['stack','expression','calculator','string'], keyInsight: 'No precedence but parentheses: keep a running result and sign; on ( push (result, sign) and reset; on ) pop and combine.', shrinkTrigger: 'on ( push state; on ) result = popped + sign*result', timeComplexity: 'O(n)', spaceComplexity: 'O(n)', gotcha: 'Maintain the current sign as +1/-1; nested parentheses are handled purely by the stack of (result, sign).', faangNote: 'Calculator family (224/227/772) is a recurring Google/Amazon set; learn the unified stack approach.', alternateApproaches: [], link: 'https://leetcode.com/problems/basic-calculator/' },
