      'LC_735':  { leetcode: 735,  title: 'Asteroid Collision', difficulty: 'Medium', freq: 'Low', status: 'Pending', templateRefs: ['P4'], tags: ['stack','simulation','array'], keyInsight: 'Stack of surviving asteroids; a right-mover then a left-mover collide — resolve by comparing magnitudes, popping the loser(s).', shrinkTrigger: 'while top>0 and cur<0: compare |top| vs |cur|', timeComplexity: 'O(n)', spaceComplexity: 'O(n)', gotcha: 'Collisions only happen for stack-top positive and current negative; equal sizes destroy both.', faangNote: null, alternateApproaches: [], link: 'https://leetcode.com/problems/asteroid-collision/' },
