    goal: 'Cover ~95% of FAANG Trie questions across 2 patterns and 9 curated problems: core prefix-tree construction/queries, and trie combined with DFS/backtracking or bit-search.',
    relatedTopics: ['backtracking', 'graph', 'bit-manipulation'],
    tagRegistry: ['trie','prefix-tree','string','dfs','backtracking','design','wildcard','autocomplete','bit-trie','xor'],
