    patterns: [
      { id: 'P1', name: 'Core Trie — Build & Query', recognitionSignals: ['Insert words and answer search / startsWith','Replace a word by its shortest root prefix','Sum or aggregate over a prefix','Autocomplete: return top matches for a typed prefix'], questionIds: ['LC_208','LC_211','LC_648','LC_677','LC_1268'] },
      { id: 'P2', name: 'Trie + DFS / Bit Search', recognitionSignals: ['Search many words simultaneously on a board/grid','Prefix AND suffix matching combined','Maximum XOR pair — use bits as a 2-way trie','Word can be formed by concatenating other words'], questionIds: ['LC_212','LC_421','LC_472','LC_745'] }
    ],
