      { id: 'P2', name: 'Greedy Scheduling / Sweep Line', recognitionSignals: ['Minimum rooms / max concurrent intervals','Can you attend all meetings','Min removals/arrows to remove overlaps','Sort by END and greedily keep non-overlapping'], questionIds: ['LC_252','LC_253','LC_435','LC_452','LC_2406'] },
      { id: 'P3', name: 'Interval Relationships', recognitionSignals: ['Intersection of two sorted interval lists','Free time across many busy schedules','Partition a string so each letter is in one piece','Two-pointer walk over two interval lists'], questionIds: ['LC_986','LC_759','LC_763'] }
