      'LC_57':   { leetcode: 57,   title: 'Insert Interval', difficulty: 'Medium', freq: 'High', status: 'Pending', templateRefs: ['P1'], tags: ['intervals','merge','two-pointers'], keyInsight: 'Input is already sorted: copy intervals ending before the new one, merge all overlapping into it, then copy the rest. One pass, no sort.', shrinkTrigger: 'three phases: before / overlapping-merge / after', timeComplexity: 'O(n)', spaceComplexity: 'O(n)', gotcha: 'Because the list is pre-sorted you do NOT re-sort; the three-phase pass is O(n).', faangNote: null, alternateApproaches: [], link: 'https://leetcode.com/problems/insert-interval/' },
