      'LC_252':  { leetcode: 252,  title: 'Meeting Rooms', difficulty: 'Easy', freq: 'High', status: 'Pending', templateRefs: ['P2'], tags: ['intervals','sorting','scheduling'], keyInsight: 'Sort by start; if any meeting starts before the previous ends, they conflict.', shrinkTrigger: 'if intervals[i].start < intervals[i-1].end: false', timeComplexity: 'O(n log n)', spaceComplexity: 'O(1)', gotcha: 'Touching endpoints (start == previous end) do NOT conflict; use strict less-than.', faangNote: 'The setup for LC_253; establishes the sort-by-start overlap check.', alternateApproaches: [], link: 'https://leetcode.com/problems/meeting-rooms/' },
